insert into public.products (id, brand, name, name_ru, description, description_ru, short_desc, price, currency, category, image_url, images, badge, in_stock, variants, bundle_items, product_type, sort_order, active) values
(2, 'Work Stuff', 'Кісточки', null, 'Набір професійних кісточок для детального чищення важкодоступних місць в авто та меблях.', null, 'null', 18, 'zł', 'tools', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/2.jpeg', '[]'::jsonb, null, true, null, null, 'product', 2, true),
(3, 'Work Stuff', 'Піноутворювач', null, 'Аксесуар для утворення піни при чистці шкіри, пластику та стелі в авто.', null, 'null', 13, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/3.jpeg', '[]'::jsonb, null, true, null, null, 'product', 3, true),
(4, 'Generic', 'Лакмусові папірці', null, 'Комплект лакмусових папірців (80 шт) для перевірки рівня pH миючих розчинів.', null, 'Для перевірки рівня pH', 8, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/4.jpeg', '[]'::jsonb, null, true, null, null, 'product', 4, true),
(5, 'Generic', 'Мікрофібра 40х40', null, 'Універсальна мікрофібра розміром 40х40 см для чистки поверхонь.', null, 'null', 7, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/5.jpeg', '[]'::jsonb, null, true, null, null, 'product', 5, true),
(7, 'Work Stuff', 'Scrub', null, 'Губка-пад для чистки шкіри, пластику та стелі в авто. Має дві сторони: мʼяку для делікатної чистки та більш грубу для складних забруднень.', null, 'null', 18, 'zł', 'tools', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/7.jpeg', '[]'::jsonb, null, true, null, null, 'product', 7, true),
(8, 'Global', 'Power Blast', null, 'Пре-спрей для синтетичних килимових покриттів. Для важких вкорінених забруднень від вугілля, бруду, піску, пилу, глини та жирних плям. Дозування: 20 г на 1.5 л гарячої води до 60°C. Вага: 300 г.', null, 'Для важких вкорінених забруднень', 30, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-power-blast-official.webp', '[]'::jsonb, null, false, '[{"size":"300гр","price":30},{"size":"1кг","price":71}]'::jsonb, null, 'product', 8, true),
(10, 'World of Clean', 'Spot Solve', null, 'Розчинниковий засіб для видалення складних плям: ручка, маркер, фарба, лак. Підходить для диванів, килимів та сидінь авто. Екологічний, без ароматизаторів, біорозкладний. Нанесіть на ганчірку та обробіть пляму методом тампонування. Готовий до використання. Обʼєм: 500 мл.', null, 'Для видалення складних плям', 79, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/10.jpeg', '[]'::jsonb, null, false, null, null, 'product', 10, true),
(11, 'Koch Chemie', 'Mehrzweckreiniger (MZR)', null, 'Високоефективний лужний очищувач (pH 12.5) для пластику та текстилю в авто. Видаляє масла, мастила, чорнило, кіптяву, нікотинові відкладення. Розведення: 1:5 – 1:50 залежно від забруднення. Нанесіть, опрацюйте щіткою, витріть мікрофіброю. Обʼєм: 1 л.', null, 'Для пластику та текстилю в авто', 58, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/11.jpeg', '[]'::jsonb, null, true, null, null, 'product', 11, true),
(12, 'Koch Chemie', 'Leather Star', null, 'Консервуючий засіб для шкіри. Використовується після основної чистки. Нанесіть на мікрофібру або аплікатор та рівномірно обробіть поверхню. Надає мʼякості та захист. Готовий до використання. Обʼєм: 1 л.', null, 'Засіб для шкіри', 65, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/12.jpeg', '[]'::jsonb, null, true, null, null, 'product', 12, true),
(13, 'Koch Chemie', 'Pol Star', null, 'Нейтральний очищувач (pH 7) для авто: шкіра, пластик, стеля, алькантара. Розведення до піноутворювача: 1:5 – 1:20. Нанесіть на щітку або скраб, проведіть чистку, зберіть залишки сухою мікрофіброю. Обʼєм: 1 л.', null, 'Нейтральний очищувач (pH 7) для авто', 54, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/13.jpeg', '[]'::jsonb, null, true, null, null, 'product', 13, true),
(14, 'Pro', 'Oxy Blast', null, 'Кисневий відбілювач та плямовивідник (pH 3.7) для синтетичних і натуральних тканин. Працює по забрудненнях: кава, вино, чай. Нанесіть на пляму, зачекайте кілька хвилин, промийте екстрактором. Готовий до використання. Обʼєм: 500 мл.', null, 'Для синтетичних і натуральних тканин', 35, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/14.jpeg', '[]'::jsonb, null, true, null, null, 'product', 14, true),
(15, 'Clinex', 'Anti Spot', null, 'Засіб на базі розчинників для видалення плям з тканини та пластику: ручки, маркери, лак, фарба, клей. Нанесіть на пляму, зберіть ватним диском, промийте екстрактором. Готовий до використання. Обʼєм: 250 мл.', null, 'Для видалення плям з тканини та пластику', 25, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/15.jpeg', '[]'::jsonb, null, true, null, null, 'product', 15, true),
(16, 'Global', 'Urine', null, 'Засіб з нейтральним pH 7 для видалення плям сечі з диванів та килимів. Наносити в чистому вигляді, зачекати 30 хвилин, промити основним миючим засобом через екстрактор. Обʼєм: 1 л.', null, 'Для видалення плям сечі з диванів та килимів', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-urine-official.webp', '[]'::jsonb, null, true, '[{"size":"1л","price":40},{"size":"5л","price":112}]'::jsonb, null, 'product', 16, true),
(17, 'Global', 'Acid Ocean', null, 'Кислотний ополіскувач (pH 3.5) для промивки диванів, сидінь авто та килимів. Додається в миючий пилосос. Дозування: 40 мл на 10 л гарячої води. Обʼєм: 1 л.', null, 'Для промивки диванів, сидінь авто та килимів', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-acid-ocean-official.jpg', '[]'::jsonb, null, true, '[{"size":"1л","price":40},{"size":"5л","price":112}]'::jsonb, null, 'product', 17, true),
(18, 'World of Clean', 'Rust Remover', null, 'Сильнокислотний засіб для видалення плям іржі та крові з тканини. Нанесіть на пляму, витріть ватним диском або білим рушником, промийте екстрактором. Готовий до використання. Обʼєм: 500 мл.', null, 'Для видалення плям іржі та крові з тканини', 60, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/18.jpeg', '[]'::jsonb, null, true, null, null, 'product', 18, true),
(19, 'Global', 'Extraction Clean S880', null, 'Основний мийний засіб pH 7,5 для екстракційного промивання диванів, килимів та салону авто після нанесення пре-спрею. Дозування: 20 г на 10 л води.', 'Основное моющее средство pH 7,5 для экстракционной промывки диванов, ковров и салона авто после нанесения пре-спрея. Дозировка: 20 г на 10 л воды.', 'Для екстракційного промивання', 34, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-extraction-25kg.jpeg', '[]'::jsonb, null, true, '[{"size":"300 г","price":34},{"size":"1 кг","price":72},{"size":"2,5 кг","price":160}]'::jsonb, null, 'product', 19, true),
(20, 'Global', 'Heavy Soil Booster', null, 'Лужний засіб (pH 11-12). Може працювати як підсилювач до пре-спреїв Power Blast та Enzym (30 мл/1 л). Також використовується нерозведеним для жирних плям. Нанесіть на 5-10 хвилин, втеріть щіткою, промийте. Обʼєм: 1 л.', null, 'Підсилювач до пре-спреїв', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-heavy-soil-official.jpg', '[]'::jsonb, null, true, null, null, 'product', 20, true),
(21, 'Global', 'Enzym Pro98', null, 'Ензимний лужний пре-спрей pH 11,8 для білкових забруднень: крові, молока, сечі, їжі та напоїв. Дозування: 15 г на 1 л води температурою до 55°C.', 'Энзимный щелочной пре-спрей pH 11,8 для белковых загрязнений: крови, молока, мочи, еды и напитков. Дозировка: 15 г на 1 л воды температурой до 55°C.', 'Ензимний пре-спрей', 38, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-enzym-25kg.jpeg', '[]'::jsonb, null, true, '[{"size":"300 г","price":38},{"size":"1 кг","price":98},{"size":"2,5 кг","price":200}]'::jsonb, null, 'product', 21, true),
(22, 'Global', 'Finish', null, 'Кислотний ополіскувач у порошку для зменшення pH після чистки. Використовується для промивки диванів, сидінь авто та килимів. Дозування: 15 г на 10 л води (в екстрактор). Вага: 500 г.', null, 'Для зменшення pH після чистки', 50, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-finish-official.webp', '[]'::jsonb, null, true, '[{"size":"500гр","price":50},{"size":"1кг","price":75}]'::jsonb, null, 'product', 22, true),
(23, 'Global', 'Single Pass', null, 'Кисневий відбілювач (pH 9.5) для матраців та світлих тканин диванів і авто. Основний миючий засіб в екстрактор. Ефективно працює під час висихання. Дозування: 20 г на 10 л води. Вага: 500 г.', null, 'Для матраців та світлих тканин диванів і авто', 50, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-single-pass-official.webp', '[]'::jsonb, null, true, '[{"size":"500гр","price":50},{"size":"1кг","price":75}]'::jsonb, null, 'product', 23, true),
(24, 'Global', 'Sta Kill', null, 'Засіб для нейтралізації неприємних біологічних запахів та плісняви (pH 7). Підходить для всіх тканин. Екстракція: 100 мл на 10 л води. Пряме нанесення: 1:4 з водою, залишити на 15-20 хв, промити. Обʼєм: 1 л.', null, 'Для нейтралізації неприємних біологічних запахів та плісняви', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-sta-kill-official.webp', '[]'::jsonb, null, true, null, null, 'product', 24, true),
(25, 'Global', 'OxyGo', null, 'Кислотний засіб (pH 3.5) для видалення плям кави, вина, чаю та слідів таніну на тканинах. Нанесіть на пляму, втирайте від країв до центру, залиште на 2-3 хв, промокніть, промийте екстрактором. Готовий до використання. Обʼєм: 500 мл.', null, 'Для видалення плям кави, вина, чаю та слідів таніну на тканинах', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-oxygo-official.webp', '[]'::jsonb, null, true, '[{"size":"500мл","price":40},{"size":"1л","price":72}]'::jsonb, null, 'product', 25, true),
(26, 'Prochem', 'Stain Pro', null, 'Лужний засіб (pH 10.5) для видалення білкових забруднень на диванах, авто, килимах: молоко, кров, йогурт, залишки їжі. Нанесіть на пляму, втирайте щіткою, залиште на 5-10 хв, промийте екстрактором. Готовий до використання. Обʼєм: 1 л.', null, 'Для видалення білкових забруднень на диванах, авто, килимах', 63, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/26.jpeg', '[]'::jsonb, null, false, null, null, 'product', 26, true),
(27, 'World of Clean', 'Solution M Power', null, 'Лужний засіб для видалення білкових забруднень: паста, кров, свіжа кава. Розпиліть на пляму, залиште на 1-2 хв, промокніть мікрофіброю (не терти), змийте водою. Готовий до використання. Обʼєм: 500 мл.', null, 'Для видалення білкових забруднень', 63, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/27.jpeg', '[]'::jsonb, null, false, null, null, 'product', 27, true),
(28, 'World of Clean', 'Eco POG', null, 'Засіб на базі розчинників для видалення плям ручок, маркерів, лаків, фарб, воску, клею з тканини. Повністю біорозкладний. Наносити лише непрямим способом через мікрофібру. Готовий до використання. Обʼєм: 500 мл.', null, 'Для видалення плям ручок, маркерів, лаків, фарб, воску, клею з тканини', 75, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/28.jpeg', '[]'::jsonb, null, false, null, null, 'product', 28, true),
(29, 'World of Clean', 'Shockwave', null, 'Ензимний лужний пре-спрей (pH 11) для білкових забруднень: їжа, напої, кров, сеча. Підходить для диванів, сидінь авто та килимів. Дозування: 20 г на 1.5 л гарячої води (50-65°C). Вага: 500 г.', null, 'Для білкових забруднень: їжа, напої, кров, сеча', 50, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/29.jpeg', '[]'::jsonb, null, true, '[{"size":"500гр","price":50},{"size":"1кг","price":75}]'::jsonb, null, 'product', 29, true),
(30, 'World of Clean', 'SPM Atlantic Breeze', null, 'Змішаний пре-спрей (pH 10) для освіжаючої чистки диванів, килимів та сидінь авто. Розпиліть на поверхню на 3-5 хв, втеріть щіткою, промийте екстрактором. Дозування: 20 г на 1.5 л води. Вага: 500 г.', null, 'Для освіжаючої чистки диванів, килимів та сидінь авто', 50, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/30.jpeg', '[]'::jsonb, null, true, '[{"size":"500гр","price":50},{"size":"1кг","price":75}]'::jsonb, null, 'product', 30, true),
(31, 'World of Clean', 'Blaze', null, 'Лужний пре-спрей на розчинниках (pH 11) для синтетичних тканин диванів і килимів. Працює по важких жирних забрудненнях. Пре-спрей: 20 г / 1.5 л води. В екстрактор: 20 г на 10 л води. Вага: 500 г.', null, 'Для синтетичних тканин диванів і килимів', 50, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/31.jpeg', '[]'::jsonb, null, true, '[{"size":"500гр","price":50},{"size":"1кг","price":75}]'::jsonb, null, 'product', 31, true),
(34, 'ADBL', 'Tickler', null, 'Губка-аплікатор для нанесення консервуючих засобів (Leather Star, Top Star, Interior Wow). Збільшений розмір у порівнянні зі стандартними аналогами.', null, 'Для нанесення консервуючих засобів', 10, 'zł', 'tools', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/34.jpeg', '[]'::jsonb, null, true, null, null, 'product', 34, true),
(35, 'Generic', 'Щітка універсальна', null, 'Універсальна щітка для чистки текстильних поверхонь.', null, 'null', 15, 'zł', 'tools', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/35.jpeg', '[]'::jsonb, null, true, null, null, 'product', 35, true),
(40, 'Fresso', 'Interior Dressing', null, 'Засіб для догляду за інтерʼєром авто. Живить, захищає та надає антисептичних властивостей пластику, гумі та вінілу. Захищає від UV-променів, не залишає слідів. Готовий до використання. Обʼєм: 500 мл.', null, 'Для догляду за інтерʼєром авто', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/40.jpeg', '[]'::jsonb, null, true, null, null, 'product', 40, true),
(41, 'Global', 'P.O.G.', null, 'Плямовивідник з високоефективними органічними розчинниками. Працює по плямах: фарба, олія, фломастери, ручки, лак для нігтів, графіті. Підходить для килимів, меблів, делікатних матеріалів. Нанесіть на ганчірку, тампонуйте від країв до центру. Обʼєм: 500 мл.', null, 'Плямовивідник з високоефективними органічними розчинниками', 75, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-pog-official.webp', '[]'::jsonb, null, true, null, null, 'product', 41, true),
(42, 'Global', 'Wool Safe', null, 'Спеціалізований пре-спрей для натуральних тканин (pH 7.8). Безпечне чищення килимів та оббивки з бавовни, бамбуку, джуту, льону та вовни. Ідеально для делікатних та плямостійких поверхонь. Розведення: 1:10. Обʼєм: 1 л.', null, 'Пре-спрей для натуральних тканин', 50, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-wool-safe-official.webp', '[]'::jsonb, null, true, null, null, 'product', 42, true),
(43, 'Generic', 'Щітка середньої жорсткості', null, 'Щітка для чистки текстильних поверхонь та шкіри. Мʼякша за червону щітку. Довжина 15 см.', null, 'null', 15, 'zł', 'tools', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/43.jpeg', '[]'::jsonb, null, true, null, null, 'product', 43, true),
(44, 'Generic', 'Рушник з мікрофібри 60х120', null, 'Рушник з мікрофібри для захисту підлоги клієнта під час хімчистки. Розмір: 60х120 см.', null, 'null', 20, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/44.jpeg', '[]'::jsonb, null, true, null, null, 'product', 44, true),
(46, 'Chemspec', 'Powdered Cotton', null, 'Професійний порошковий засіб для оббивки з натуральної та гаїтянської бавовни. Усуває коричневі плями після сушки. Дозування: 3 мірні ложки на 4 л теплої води. Ідеально для бавовни, схильної до потемніння. Вага: 500 г.', null, 'Для оббивки з натуральної та гаїтянської бавовни', 60, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/chemspec-cotton-upholstery-official.jpg', '[]'::jsonb, null, true, null, null, 'product', 46, true),
