(51, 'Global', 'Citra X Out', null, 'Концентрований ароматизатор і нейтралізатор запахів з цитрусово-лаймовим ароматом. Видаляє запахи тварин, їжі, диму, вологи. В розпилювач: 1:4. В екстрактор: 1:100. Обʼєм: 1 л.', null, 'Концентрований ароматизатор і нейтралізатор запахів', 40, 'zł', 'chemistry', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/global-citra-x-out-official.webp', '[]'::jsonb, null, true, null, null, 'product', 51, true),
(57, 'Generic', 'Сумка для транспортування', null, 'Міцна сумка для транспортування хімії та інструментів для хімчистки. Розміри: 50х30х40 см. Кольори: синій, чорний.', null, 'null', 180, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/57.jpeg', '[]'::jsonb, null, true, null, null, 'product', 57, true),
(62, 'Santoemma', 'SW15 (Mini)', null, 'Професійний миючий пилосос. Вага: 12 кг. Баки: 14 л. Помпа: 4 бар. Мотор: 1500W. Повністю новий. Доступний лише при покупці у Вроцлаві (без відправки).', null, 'Професійний миючий пилосос', 3400, 'zł', 'equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/62.jpeg', '[]'::jsonb, null, true, null, null, 'product', 62, true),
(63, 'Work Stuff', 'Розпилювач', null, 'Професійний розпилювач для нанесення хімії. Підходить для детейлінгу та хімчистки меблів. Стійкий до хімії. Обʼєм: 1 л.', null, 'Розпилювач для нанесення хімії', 17, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/63.jpeg', '[]'::jsonb, null, true, null, null, 'product', 63, true),
(64, 'Generic', 'Мікрофібра мʼяка', null, 'Мʼяка мікрофібра преміум-якості. Розмір: 40х40 см. Щільність: 320 г/м².', null, 'null', 7, 'zł', 'accessories', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/64.jpeg', '[]'::jsonb, null, true, null, null, 'product', 64, true),
