(85, 'Unger', 'Шубка Monsoon, 35 см', null, 'Професійна шубка з високою здатністю утримувати воду та збирати забруднення.', 'Профессиональная шубка с высокой способностью удерживать воду и собирать загрязнения.', 'Шубка для миття вікон', 58, 'zł', 'window-equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/unger-monsoon-sleeve-35.jpeg', '[]'::jsonb, null, true, null, null, 'product', 85, true),
(86, 'Unger', 'Скребок ErgoTec, 15 см', null, 'Скребок для видалення стійких забруднень зі скла. Використовуйте на змоченій поверхні та попередньо перевірте сумісність скла.', 'Скребок для удаления стойких загрязнений со стекла. Используйте на смоченной поверхности и предварительно проверьте совместимость стекла.', 'Для важких забруднень', 90, 'zł', 'window-equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/unger-ergotec-scraper-15.jpeg', '[]'::jsonb, null, true, null, null, 'product', 86, true),
(87, 'Unger', 'Запасні леза для скребка, 15 см — 25 шт.', null, 'Комплект із 25 запасних лез шириною 15 см для скребка Unger.', 'Комплект из 25 запасных лезвий шириной 15 см для скребка Unger.', '25 запасних лез', 75, 'zł', 'window-equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/unger-scraper-blades-15.jpeg', '[]'::jsonb, null, true, null, null, 'product', 87, true),
(88, 'Unger', 'Запасна гумка Soft, 35 см', null, 'М’яка запасна гумка для згону Unger, ефективна за нижчої температури та на гладких поверхнях.', 'Мягкая запасная резинка для сгона Unger, эффективная при низкой температуре и на гладких поверхностях.', 'М’яка гумка, 35 см', 14, 'zł', 'window-equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/unger-soft-rubber-35.jpeg', '[]'::jsonb, null, true, null, null, 'product', 88, true),
(89, 'Unger', 'Тримач для пада', null, 'Ручний тримач для пада, призначений для очищення скла та інших гладких поверхонь.', 'Ручной держатель для пада, предназначенный для очистки стекла и других гладких поверхностей.', 'Ручний тримач', 40, 'zł', 'window-equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/window-pad-holder.jpeg', '[]'::jsonb, null, true, null, null, 'product', 89, true),
(90, 'Unger', 'Білий пад для видалення забруднень', null, 'М’який білий пад для делікатного очищення забруднень зі скла та гладких поверхонь.', 'Мягкий белый пад для деликатной очистки загрязнений со стекла и гладких поверхностей.', 'М’який очищувальний пад', 6, 'zł', 'window-equipment', 'https://fwjisaaorqubsjkdyidx.supabase.co/storage/v1/object/public/products/window-white-pad.jpeg', '[]'::jsonb, null, true, null, null, 'product', 90, true),
(1001, 'CleanTapi', 'Готовий набір «Старт»', 'Готовый набор «Старт»', 'Мінімальний стартовий набір хімії для хімчистки меблів, сидінь авто та килимів. Цих засобів вистачить на хімчистку 8–10 диванів. Ціна вже з доставкою по Польщі.', 'Минимальный стартовый набор химии для химчистки мебели, сидений авто и ковров. Средств хватит на химчистку 8–10 диванов. Цена уже с доставкой по Польше.', null, 330, 'zł', 'sets', null, '[]'::jsonb, null, true, null, '[{"productId":"21","name":"Global Enzym","amount":"300 г","qty":1},{"productId":"19","name":"Global Extraction","amount":"300 г","qty":1},{"productId":"17","name":"Global Acid Ocean","amount":"1 л","qty":1},{"productId":"16","name":"Global Urine","amount":"1 л","qty":1},{"productId":"25","name":"Global OxyGo","amount":"500 мл","qty":1},{"productId":"24","name":"Global Sta Kill","amount":"500 мл","qty":1},{"productId":"26","name":"Global Stain Pro","amount":"250 мл","qty":1},{"productId":"10","name":"World of Clean Spot Solve","amount":"250 мл","qty":1}]'::jsonb, 'bundle', 1001, true),
(1002, 'CleanTapi', 'Готовий набір «Стандарт»', 'Готовый набор «Стандарт»', 'Стандартний набір засобів для хімчистки меблів, сидінь авто та килимів. Цих засобів буде достатньо для хімчистки 35–45 диванів. Ціна вже з доставкою по Польщі.', 'Стандартный набор средств для химчистки мебели, сидений авто и ковров. Средств будет достаточно для химчистки 35–45 диванов. Цена уже с доставкой по Польше.', null, 580, 'zł', 'sets', null, '[]'::jsonb, 'Найпопулярніший', true, null, '[{"productId":"21","name":"Global Enzym","amount":"300 г","qty":1},{"productId":"21","name":"Global Enzym","amount":"1 кг","qty":1},{"productId":"19","name":"Global Extraction","amount":"1 кг","qty":1},{"productId":"17","name":"Global Acid Ocean","amount":"5 л","qty":1},{"productId":"16","name":"Global Urine","amount":"1 л","qty":1},{"productId":"24","name":"Global Sta Kill","amount":"1 л","qty":1},{"productId":"28","name":"World of Clean Eco POG","amount":"500 мл","qty":1},{"productId":"27","name":"World of Clean Solution M Power","amount":"500 мл","qty":1},{"productId":"25","name":"Global OxyGo","amount":"500 мл","qty":1},{"productId":"30","name":"World of Clean SPM Atlantic Breeze","amount":"500 г","qty":1},{"productId":"4","name":"Лакмусові папірці","amount":"1 шт","qty":1}]'::jsonb, 'bundle', 1002, true),
