-- CleanTapi: one Supabase source for products, galleries and ready-made sets

alter table public.products
  add column if not exists name_ru text,
  add column if not exists description_ru text,
  add column if not exists images jsonb not null default '[]'::jsonb,
  add column if not exists bundle_items jsonb,
  add column if not exists product_type text not null default 'product',
  add column if not exists sort_order integer not null default 0,
  add column if not exists active boolean not null default true,
  add column if not exists updated_at timestamptz not null default now();

on conflict (id) do update set
  brand = excluded.brand,
  name = excluded.name,
  name_ru = excluded.name_ru,
  description = excluded.description,
  description_ru = excluded.description_ru,
  short_desc = excluded.short_desc,
  price = excluded.price,
  currency = excluded.currency,
  category = excluded.category,
  image_url = excluded.image_url,
  images = excluded.images,
  badge = excluded.badge,
  in_stock = excluded.in_stock,
  variants = excluded.variants,
  bundle_items = excluded.bundle_items,
  product_type = excluded.product_type,
  sort_order = excluded.sort_order,
  active = excluded.active,
  updated_at = now();
